        --line: #d9d2c7;
        --shadow: 0 24px 60px rgba(24, 33, 31, 0.12);
        --radius-lg: 30px;
        --radius-md: 20px;
        --radius-sm: 14px;
        --container: min(1180px, calc(100vw - 32px));
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(247, 223, 196, 0.9), transparent 34rem),
          linear-gradient(180deg, #fbf7ef 0%, var(--bg) 48%, #f3efe8 100%);
        color: var(--ink);
        font-size: 16px;
        line-height: 1.5;
      }

      body,
      button,
      input {
        font: inherit;
      }

      img {
        display: block;
        max-width: 100%;
      }

      a {
        color: inherit;
        text-decoration-thickness: 0.08em;
        text-underline-offset: 0.22em;
      }

      a:hover {
        color: var(--brand);
      }

      :focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 4px;
      }

      .skip-link {
        position: absolute;
        left: 16px;
        top: 12px;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--ink);
        color: #fff;
        padding: 10px 16px;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .container {
        width: var(--container);
        margin-inline: auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 5;
        border-bottom: 1px solid rgba(217, 210, 199, 0.82);
        background: rgba(255, 253, 249, 0.9);
        backdrop-filter: blur(18px);
      }

      .header-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 24px;
        min-height: 78px;
      }

      .brand-mark {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        color: var(--ink);
        font-weight: 800;
        letter-spacing: -0.04em;
        text-decoration: none;
      }

      .brand-icon {
        display: grid;
        width: 42px;
        height: 42px;
        place-items: center;
        border-radius: 14px;
        background: var(--brand);
        color: #fff;
        font-weight: 900;
      }

      .nav-list,
      .footer-list {
        display: flex;
        align-items: center;
        gap: 8px;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .nav-list a,
      .footer-list a {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        border-radius: 999px;
        padding: 8px 13px;
        color: var(--muted);
        font-weight: 700;
        text-decoration: none;
      }

      .nav-list a:hover,
      .footer-list a:hover {
        background: rgba(11, 95, 83, 0.08);
        color: var(--brand);
      }

      .header-actions {
        display: flex;
        align-items: center;
        gap: 10px;
      }

      .icon-button,
      .button {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        justify-content: center;
        border: 0;
        border-radius: 999px;
        cursor: pointer;
        font-weight: 800;
        text-decoration: none;
      }

      .icon-button {
        width: 44px;
        background: #f0ebe3;
        color: var(--ink);
      }

      .button {
        gap: 8px;
        padding: 12px 18px;
        background: var(--brand);
        color: #fff;
        box-shadow: 0 10px 20px rgba(11, 95, 83, 0.16);
      }

      .button:hover {
        background: var(--brand-strong);
        color: #fff;
      }

      .button.secondary {
        border: 1px solid var(--line);
        background: var(--surface);
        color: var(--ink);
        box-shadow: none;
      }

      .button.secondary:hover {
        border-color: var(--brand);
        color: var(--brand);
      }

      main {
        outline: none;
      }

      .hero {
        padding: 56px 0 40px;
      }

      .hero-grid {
        display: grid;
        grid-template-columns: minmax(0, 1.08fr) minmax(320px, 0.92fr);
        gap: 28px;
        align-items: stretch;
      }

      .hero-copy,
      .hero-card {
        border: 1px solid rgba(217, 210, 199, 0.9);
        border-radius: var(--radius-lg);
        background: rgba(255, 253, 249, 0.82);
        box-shadow: var(--shadow);
      }

      .hero-copy {
        display: flex;
        min-height: 540px;
        flex-direction: column;
        justify-content: space-between;
        padding: clamp(28px, 6vw, 64px);
      }

      .eyebrow {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 8px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: #75330f;
        font-size: 0.82rem;
        font-weight: 900;
        letter-spacing: 0.08em;
        padding: 7px 12px;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        color: var(--ink);
        line-height: 1.02;
      }

      h1 {
        max-width: 11ch;
        font-size: clamp(3rem, 8vw, 7.25rem);
        letter-spacing: -0.08em;
      }

      h2 {
        font-size: clamp(2rem, 4vw, 3.6rem);
        letter-spacing: -0.06em;
      }

      h3 {
        font-size: 1.12rem;
        letter-spacing: -0.025em;
      }

      .lede {
        max-width: 58ch;
        color: var(--muted);
        font-size: clamp(1.05rem, 2vw, 1.28rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        margin-top: 28px;
      }

      .hero-stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 12px;
        margin: 34px 0 0;
        padding: 0;
        list-style: none;
      }

      .hero-stats li {
        border-radius: var(--radius-sm);
        background: #f1ece3;
        padding: 16px;
      }

      .hero-stats strong {
        display: block;
        font-size: 1.4rem;
        line-height: 1;
      }

      .hero-stats span {
        display: block;
        margin-top: 6px;
        color: var(--muted);
        font-size: 0.9rem;
      }

      .hero-card {
        display: grid;
        overflow: hidden;
      }

      .hero-product-visual {
        min-height: 360px;
        background:
          radial-gradient(circle at 70% 25%, rgba(255, 255, 255, 0.9) 0 10%, transparent 11%),
          radial-gradient(circle at 24% 35%, #d9692b 0 13%, transparent 14%),
          radial-gradient(circle at 62% 62%, #f7dfc4 0 19%, transparent 20%),
          linear-gradient(135deg, #0b5f53, #93aa77);
      }

      .hero-card-content {
        padding: 26px;
      }

      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        margin-top: 16px;
      }

      .price {
        font-size: 1.5rem;
        font-weight: 900;
      }

      .muted {
        color: var(--muted);
      }

      .section {
        padding: 42px 0;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 24px;
        margin-bottom: 22px;
      }

      .section-header p {
        max-width: 48ch;
        margin: 10px 0 0;
        color: var(--muted);
      }

      .product-grid {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 18px;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .product-card,
      .deal-card,
      .editorial-card,
      .newsletter {
        border: 1px solid var(--line);
        border-radius: var(--radius-md);
        background: var(--surface-strong);
        box-shadow: 0 12px 30px rgba(24, 33, 31, 0.08);
      }

      .product-card {
        display: flex;
        min-height: 100%;
        flex-direction: column;
        overflow: hidden;
      }

      .product-art {
        display: grid;
        min-height: 230px;
        place-items: end start;
        padding: 16px;
        background:
          radial-gradient(circle at 75% 25%, rgba(255, 255, 255, 0.85) 0 13%, transparent 14%),
          var(--card-bg);
      }

      .product-badge,
      .deal-badge {
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.86);
        color: var(--brand-strong);
        font-size: 0.78rem;
        font-weight: 900;
        padding: 7px 10px;
      }

      .product-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        gap: 12px;
        padding: 18px;
      }

      .product-title-link {
        text-decoration: none;
      }

      .product-title-link:hover h3 {
        color: var(--brand);
        text-decoration: underline;
        text-decoration-thickness: 0.08em;
        text-underline-offset: 0.22em;
      }

      .product-meta {
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 12px;
        margin-top: auto;
      }

      .rating {
        color: #7a4b00;
        font-size: 0.92rem;
        font-weight: 800;
      }

      .card-actions {
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 10px;
        margin-top: 4px;
      }

      .save-button {
        width: 44px;
        border: 1px solid var(--line);
        background: #fff;
        color: var(--brand);
        box-shadow: none;
      }

      .deals-grid {
        display: grid;
        grid-template-columns: 1.15fr 0.85fr;
        gap: 18px;
      }

      .deal-card {
        display: grid;
        min-height: 300px;
        overflow: hidden;
        background: var(--deal-bg);
      }

      .deal-card.large {
        grid-template-columns: 1fr 0.82fr;
      }

      .deal-copy {
        display: flex;
        flex-direction: column;
        align-items: start;
        justify-content: center;
        gap: 16px;
        padding: clamp(24px, 5vw, 44px);
      }

      .deal-copy h3 {
        font-size: clamp(1.9rem, 4vw, 3rem);
        letter-spacing: -0.06em;
      }

      .deal-visual {
        min-height: 240px;
        background:
          radial-gradient(circle at 46% 35%, rgba(255, 255, 255, 0.8) 0 16%, transparent 17%),
          radial-gradient(circle at 68% 62%, rgba(255, 255, 255, 0.42) 0 24%, transparent 25%),
          linear-gradient(140deg, rgba(255, 255, 255, 0.22), transparent);
      }

      .deal-stack {
        display: grid;
        gap: 18px;
      }

      .deal-stack .deal-card {
        min-height: 141px;
      }

      .editorial-grid {
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        gap: 18px;
      }

      .editorial-card {
        overflow: hidden;
      }

      .editorial-art {
        min-height: 190px;
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.18), transparent),
          var(--article-bg);
      }

      .editorial-body {
        padding: 20px;
      }

      .editorial-body p {
        color: var(--muted);
      }

      .editorial-meta {
        color: var(--brand-strong);
        font-size: 0.82rem;
        font-weight: 900;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      .newsletter {
        display: grid;
        grid-template-columns: 1fr minmax(280px, 0.76fr);
        gap: 20px;
        align-items: center;
        margin: 44px 0;
        padding: clamp(24px, 5vw, 44px);
        background:
          radial-gradient(circle at 95% 0%, rgba(217, 105, 43, 0.18), transparent 23rem),
          var(--surface-strong);
      }

      .newsletter p {
        max-width: 56ch;
        color: var(--muted);
      }

      .newsletter-form {
        display: flex;
        gap: 10px;
      }

      .newsletter-form label {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        white-space: nowrap;
      }

      .newsletter-form input {
        min-width: 0;
        flex: 1;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: #fff;
        color: var(--ink);
        padding: 12px 16px;
      }

      .form-help {
        margin: 8px 0 0;
        color: var(--muted);
        font-size: 0.9rem;
      }

      .status-message {
        min-height: 1.5em;
        margin: 8px 0 0;
        color: var(--brand-strong);
        font-weight: 800;
      }

      .site-footer {
        border-top: 1px solid var(--line);
        padding: 34px 0;
        background: #ece6db;
      }

      .footer-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 24px;
      }

      .footer-note {
        margin: 6px 0 0;
        color: var(--muted);
      }

      @media (prefers-reduced-motion: no-preference) {
        .button,
        .icon-button,
        a,
        .product-card,
        .deal-card,
        .editorial-card {
          transition:
            transform 180ms ease,
            background-color 180ms ease,
            border-color 180ms ease,
            color 180ms ease,
            box-shadow 180ms ease;
        }

        .product-card:hover,
        .deal-card:hover,
        .editorial-card:hover {
          transform: translateY(-3px);
          box-shadow: 0 18px 42px rgba(24, 33, 31, 0.12);
        }
      }

      @media (forced-colors: active) {
        .site-header,
        .hero-copy,
        .hero-card,
        .product-card,
        .deal-card,
        .editorial-card,
        .newsletter,
        .icon-button,
        .button.secondary,
        .newsletter-form input {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .button,
        .brand-icon {
          border: 1px solid ButtonText;
        }

        .product-art,
        .deal-card,
        .editorial-art,
        .hero-product-visual {
          forced-color-adjust: none;
        }
      }

      @media (max-width: 960px) {
        .header-inner,
        .footer-inner {
          align-items: flex-start;
          flex-direction: column;
          padding: 18px 0;
        }

        .hero-grid,
        .deals-grid,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .hero-copy {
          min-height: auto;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 680px) {
        :root {
          --container: min(100vw - 24px, 1180px);
        }

        .nav-list,
        .footer-list,
        .hero-stats,
        .newsletter-form,
        .section-header,
        .price-row {
          align-items: stretch;
          flex-direction: column;
        }

        .nav-list,
        .footer-list {
          width: 100%;
        }

        .nav-list a,
        .footer-list a {
          width: 100%;
        }

        .header-actions {
          width: 100%;
        }

        .header-actions .button {
          flex: 1;
        }

        .hero {
          padding-top: 28px;
        }

        .hero-stats,
        .product-grid,
        .editorial-grid,
        .deal-card.large,
        .card-actions {
          grid-template-columns: 1fr;
        }

        .product-art {
          min-height: 190px;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="root"></div>

    <script>
      const products = [
        {
          name: "Linen Utility Jacket",
          category: "New arrival",
          price: "$128",
          rating: "4.8 stars",
          href: "#linen-utility-jacket",
          colors: "linear-gradient(135deg, #e9d6bd, #a6b59d)",
        },
        {
          name: "Cloud Knit Throw",
          category: "Home favorite",
          price: "$74",
          rating: "4.9 stars",
          href: "#cloud-knit-throw",
          colors: "linear-gradient(135deg, #e8ece7, #b6c5d8)",
        },
        {
          name: "Everyday Market Tote",
          category: "Best seller",
          price: "$42",
          rating: "4.7 stars",
          href: "#everyday-market-tote",
          colors: "linear-gradient(135deg, #f7dfc4, #d9692b)",
        },
        {
          name: "Stoneware Dining Set",
          category: "Limited batch",
          price: "$96",
          rating: "4.8 stars",
          href: "#stoneware-dining-set",
          colors: "linear-gradient(135deg, #ddd5ca, #68756e)",
        },
      ];

      const editorials = [
        {
          title: "How to build a capsule wardrobe for spring",
          kicker: "Style guide",
          summary: "Five versatile textures, breathable layers, and silhouettes our buyers are backing this season.",
          href: "#capsule-wardrobe",
          colors: "linear-gradient(135deg, #0b5f53, #93aa77)",
        },
        {
          title: "Inside our responsible cotton collection",
          kicker: "Behind the brand",
          summary: "Meet the partner mills helping us reduce water use while keeping everyday staples soft.",
          href: "#responsible-cotton",
          colors: "linear-gradient(135deg, #2f3c37, #d9d2c7)",
        },
        {
          title: "Dinner party details under $50",
          kicker: "Home edit",
          summary: "Small upgrades that make the table feel considered, from sculptural glass to woven linens.",
          href: "#dinner-party",
          colors: "linear-gradient(135deg, #d9692b, #f7dfc4)",
        },
      ];

      const html = String.raw;

      function Header() {
        return html`
          <header class="site-header">
            <div class="container header-inner">
              <a class="brand-mark" href="#top" aria-label="North and Field home">
                <span class="brand-icon" aria-hidden="true">N</span>
                <span>North &amp; Field</span>
              </a>
              <nav aria-label="Primary">
                <ul class="nav-list">
                  <li><a href="#featured">Featured</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Editorial</a></li>
                  <li><a href="#newsletter">Join</a></li>
                </ul>
              </nav>
              <div class="header-actions" aria-label="Shopping actions">
                <button class="icon-button" type="button" aria-label="Search products">⌕</button>
                <a class="button" href="#featured">Shop new arrivals</a>
              </div>
            </div>
          </header>
        `;
      }

      function Hero() {
        return html`
          <section class="hero" aria-labelledby="hero-heading">
            <div class="container hero-grid">
              <div class="hero-copy">
                <div>
                  <p class="eyebrow">Spring retail edit</p>
                  <h1 id="hero-heading">Modern goods for every day</h1>
                  <p class="lede">
                    Discover refined wardrobe staples, thoughtful home pieces, and fresh seasonal finds curated for comfort,
                    durability, and effortless style.
                  </p>
                  <div class="hero-actions">
                    <a class="button" href="#featured">Shop featured products</a>
                    <a class="button secondary" href="#editorial">Read the edit</a>
                  </div>
                </div>
                <ul class="hero-stats" aria-label="Store highlights">
                  <li><strong>2-day</strong><span>delivery on essentials</span></li>
                  <li><strong>4.8</strong><span>average product rating</span></li>
                  <li><strong>120+</strong><span>new seasonal arrivals</span></li>
                </ul>
              </div>
              <article class="hero-card" aria-labelledby="hero-product-heading">
                <div class="hero-product-visual" role="img" aria-label="Abstract arrangement of seasonal retail products"></div>
                <div class="hero-card-content">
                  <p class="eyebrow">Featured drop</p>
                  <h2 id="hero-product-heading">The Weekend Set</h2>
                  <p class="muted">A coordinated linen overshirt, relaxed trouser, and structured tote in soft neutral tones.</p>
                  <div class="price-row">
                    <span class="price">$168 bundle</span>
                    <a class="button secondary" href="#weekend-set">View bundle</a>
                  </div>
                </div>
              </article>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        return html`
          <li>
            <article class="product-card">
              <div class="product-art" style="--card-bg: ${product.colors}" role="img" aria-label="${product.name} product photo">
                <span class="product-badge">${product.category}</span>
              </div>
              <div class="product-body">
                <a class="product-title-link" href="${product.href}">
                  <h3>${product.name}</h3>
                </a>
                <div class="product-meta">
                  <span class="price">${product.price}</span>
                  <span class="rating" aria-label="${product.rating}">★ ${product.rating.replace(" stars", "")}</span>
                </div>
                <div class="card-actions">
                  <button class="button" type="button" aria-label="Add to cart: ${product.name}">Add to cart</button>
                  <button class="icon-button save-button" type="button" aria-label="Save for later: ${product.name}">♡</button>
                </div>
              </div>
            </article>
          </li>
        `;
      }

      function FeaturedProducts() {
        return html`
          <section class="section" id="featured" aria-labelledby="featured-heading">
            <div class="container">
              <div class="section-header">
                <div>
                  <p class="eyebrow">Featured products</p>
                  <h2 id="featured-heading">Fresh finds, ready now</h2>
                  <p>Customer-loved pieces selected for quality materials, versatile palettes, and everyday usefulness.</p>
                </div>
                <a class="button secondary" href="#all-products">View all products</a>
              </div>
              <ul class="product-grid">
                ${products.map(ProductCard).join("")}
              </ul>
            </div>
          </section>
        `;
      }

      function Deals() {
        return html`
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="container">
              <div class="section-header">
                <div>
                  <p class="eyebrow">Limited deals</p>
                  <h2 id="deals-heading">Smart savings this week</h2>
                  <p>Timed offers on elevated essentials, curated bundles, and pieces that make daily routines feel better.</p>
                </div>
              </div>
              <div class="deals-grid">
                <article class="deal-card large" style="--deal-bg: linear-gradient(135deg, #113f39, #0b5f53)" aria-labelledby="deal-main-heading">
                  <div class="deal-copy">
                    <span class="deal-badge">Save 25%</span>
                    <h3 id="deal-main-heading">Home reset bundle</h3>
                    <p class="muted">Layer woven storage, stoneware serve pieces, and soft cotton towels for less.</p>
                    <a class="button" href="#home-reset-bundle">Shop the bundle</a>
                  </div>
                  <div class="deal-visual" aria-hidden="true"></div>
                </article>
                <div class="deal-stack">
