const fs = require('fs');
const { chromium } = require('playwright');

(async () => {
  const axePath = require.resolve('axe-core/axe.min.js');
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const results = [];

  for (const viewport of [{ width: 1366, height: 900 }, { width: 320, height: 900 }]) {
    const page = await browser.newPage({ viewport });
    await page.setContent(html, { waitUntil: 'load' });
    await page.addScriptTag({ path: axePath });
    const result = await page.evaluate(async () => await window.axe.run());
    results.push({ viewport, violations: result.violations });
    await page.close();
  }

  const page = await browser.newPage({ viewport: { width: 1366, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.click('.newsletter-form button[type="submit"]');
  const invalidState = await page.locator('#email').getAttribute('aria-invalid');
  const statusText = await page.locator('#email-status').textContent();
  const focusedId = await page.evaluate(() => document.activeElement.id);
  await browser.close();

  const violations = results.flatMap(({ viewport, violations }) =>
    violations.map((v) => ({ ...v, viewport }))
  );
  const wcag = violations.filter((v) => !(v.tags || []).includes('best-practice'));
  const bp = violations.filter((v) => (v.tags || []).includes('best-practice'));
  const formCheckFailed = invalidState !== 'true' || !/^Error:/.test(statusText || '') || focusedId !== 'email';
  console.log(JSON.stringify({
    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, viewport: v.viewport, targets: v.nodes.map((n) => n.target) })),
    bp: bp.map((v) => ({ id: v.id, viewport: v.viewport, targets: v.nodes.map((n) => n.target) })),
    formInvalidState: { invalidState, statusText, focusedId }
  }, null, 2));
  process.exit(wcag.length || formCheckFailed ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
